// class
class flake {
	constructor() {
		this.cutA = floor(random(5, 12));  // number of cuts on one side
		this.cutB = floor(random(4, 12));  // and on the other
		this.step = 0;  // used to animate
		this.done = false;  //once the flake as been cut and unfolded
		this.pg = null;  // pgraphic used to create the reflected snowflake

		// 1/12 of a snowflake
		this.pg = createGraphics(800, 800);
		this.pg.background(0, 0, 0, 0); //transparent
		this.pg.fill(255);
		this.pg.stroke(255);
		this.pg.strokeJoin(MITER);
		this.pg.strokeCap(PROJECT);
		this.pg.noStroke()
		this.pg.beginShape();
		this.pg.vertex(0, 0);
		this.pg.vertex(this.pg.width, 0);
		this.pg.vertex(this.pg.width * cos(TAU / 12), this.pg.width * sin(TAU / 12));
		this.pg.endShape(CLOSE);
	}

	display(_x, _y, _sz) {
		if (this.step <= this.cutA + this.cutB) { //still cutting bits out
			let p1 = createVector(0, 0);
			let p2 = createVector(0, 0);
			let p3 = createVector(0, 0);
			if (this.step == 0) { //blunt the end
				p1.set(this.pg.width + random(-0.75 * this.pg.width, 0), 0);
				p2.set(this.pg.width * 2, 0);
				p3.set(this.pg.width, this.pg.width * sin(TAU / 12));

			} else if (this.step <= this.cutA) { //side let p1.set(random(0, this.pg.width), 0);
				p2.set(random(p1.x, this.pg.width), 0);
				p3.set(random(p1.x, p2.x), 0);
				p3.set(p3.x, random(0, 0.75 * p3.x * sin(TAU / 12)));
			} else { // side let p1.set(random(0, this.pg.width), 10);
				p2.set(random(p1.x, this.pg.width), 10);
				p3.set(random(p1.x, p2.x), 0);
				p3.set(p3.x, random(0, -0.25 * p3.x * sin(TAU / 12)));
			}

			if (this.step == this.cutA) {  //rotate the shape to cut side b
				this.pg.rotate(TAU / 12);
			}

			this.pg.blendMode(REMOVE);   //make the cut
			this.pg.strokeWeight(2);
			this.pg.beginShape();
			this.pg.vertex(p1.x, p1.y);
			this.pg.vertex(p2.x, p2.y);
			this.pg.vertex(p3.x, p3.y);
			this.pg.endShape(CLOSE);

			push();
			translate(_x, _y);
			scale(0.5 * _sz / 800);
			image(this.pg, 0, 0); // draw the piece

			if (this.step >= this.cutA) {
				rotate(TAU / 12);  //rotate the context to show the b cuts let he right place
			}
			//visualize the cut
			strokeWeight(1);
			stroke('red');
			fill('red')
			beginShape();
			vertex(p1.x, p1.y);
			vertex(p2.x, p2.y);
			vertex(p3.x, p3.y);
			endShape(CLOSE);
			pop();

		} else {  // done cutting, just draw the full snowflake

			push();
			translate(_x, _y);
			scale(0.5 * _sz / 800);
			for (let i = 0; i < this.step - this.cutA + this.cutB - 12; i++) {  //animated 
				image(this.pg, 0,0)
				image(this.pg, 0,0)
				scale(1, -1);
				image(this.pg, 0,0)
				image(this.pg, 0,0)
				scale(1, -1);
				rotate(TAU / 6);
			}
			pop();

		}
		if (this.step <= this.cutA + this.cutB + 12) {  //done cutting and unfolding
			this.step++;
		} else {
			this.done = true;
		}
	}
}

